package org.example.idf_service.repository; import org.example.idf_service.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.time.LocalDate; import java.util.*;
public interface MonthLockRepository extends JpaRepository<AccountMonthLock,Long> { @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select l from AccountMonthLock l where l.accountFrom=:account and l.monthStart=:month and l.category=:category") Optional<AccountMonthLock> lock(@Param("account") String account,@Param("month") LocalDate month,@Param("category") ExpenseCategory category); }
